drop policy if exists "contest_entries_owner_insert" on public.contest_entries; create policy "contest_entries_owner_insert" on public.contest_entries for insert to authenticated with check ((select auth.uid()) = user_id and exists(select 1 from public.contests c where c.id=contest_entries.contest_id and c.status='active' and (c.starts_at is null or c.starts_at <= now()) and (c.ends_at is null or c.ends_at > now()))); drop policy if exists "promotion_redemptions_own_insert" on public.promotion_redemptions; create policy "promotion_redemptions_own_insert" on public.promotion_redemptions for insert to authenticated with check ((select auth.uid()) = user_id and exists(select 1 from public.promotions p where p.id=promotion_redemptions.promotion_id and p.active=true and (p.starts_at is null or p.starts_at <= now()) and (p.ends_at is null or p.ends_at > now())));
